window.__APP_CHUNKS=window.__APP_CHUNKS||[];window.__APP_CHUNKS[10]="\", \"origin\": \"Астрахань\", \"summary\": \"Самая большая личная база: Ахтубинск, Заволжское, Красный Яр и городская точка. Здесь уже есть сильные успешные и неудачные сезоны для сравнения.\", \"status\": \"Ключевой регион\", \"targets\": [\"Судак\", \"Щука\", \"Жерех\", \"Окунь\", \"Мирная рыба\"], \"methods\": [\"VIB / раттлины\", \"Живец на отводном\", \"Воблеры\", \"Фидер\"], \"water_terms\": [\"Астрахан\"], \"diary_terms\": [\"заволж\", \"астрахан\"], \"research\": [\"Сравнить гидрологию 2021/2022 с провальным Заволжским 2023.\", \"Разобрать экстремально высокую воду Красного Яра в мае 2023.\", \"Восстановить точные точки ерика Казачий, Маячной и Кривого Бузана.\"]}, \"Дагестан\": {\"image\": \"data:image/webp;base64,\", \"origin\": \"Махачкала\", \"summary\": \"Две разные системы: морской берег Избербаша и горный Сулак. Главная ценность — очень сильные контрасты условий, которые можно проверять по погоде и гидрологии.\", \"status\": \"Исследовательский регион\", \"targets\": [\"Кутум\", \"Вобла\", \"Щука\"], \"methods\": [\"Береговая донная ловля\", \"Спиннинг\"], \"water_terms\": [\"Дагестан\"], \"diary_terms\": [\"избербаш\", \"дагест\", \"сулак\"], \"research\": [\"Сопоставить Избербаш 22–23.08.2020 и 05–07.10.2025 по ветру, волне и SST.\", \"Поднять уровни/расход и режим гидроузлов Сулака на 05–11.10.2025.\", \"Разделять морские и речные факторы — это две разные модели.\"]}, \"Подмосковье\": {\"image\": \"data:image/webp;base64,\", \"origin\": \"Щербинка\", \"summary\": \"Пока это не архив личных уловов, а рабочий регион для подбора коротких выездов. Основная задача — искать реальные варианты на 1–2 ночи без собственного автомобиля.\", \"status\": \"Регион поиска\", \"targets\": [\"Щука\", \"Судак\"], \"methods\": [\"Джиг\", \"VIB / раттлины\", \"Воблеры\"], \"water_terms\": [], \"diary_terms\": [\"щербин\", \"подмосков\", \"ока\"], \"research\": [\"Ока в Калужской области.\", \"Ока в районе Рязани / Шилово / Спасска.\", \"Иваньковское водохранилище / Конаково.\", \"Углич / Калязин и участки Волги.\"]}};\n\nfunction relatedWaterbodies(regionName){\n  const cfg = REGION_DETAIL[regionName];\n  if(!cfg) return [];\n  if(!cfg.water_terms.length) return [];\n  return PROJECT_DB.waterbodies.filter(w => cfg.water_terms.some(t =>\n    (w.region + ' ' + w.name).toLowerCase().includes(t.toLowerCase())\n  ));\n}\n\nfunction relatedDiary(regionName){\n  const cfg = REGION_DETAIL[regionName];\n  if(!cfg) return [];\n  return DATA.diary.filter(d => cfg.diary_terms.some(t =>\n    (d.place + ' ' + d.conclusion).toLowerCase().includes(t.toLowerCase())\n  ));\n}\n\nfunction openRegion(regionName){\n  const cfg = REGION_DETAIL[regionName];\n  if(!cfg) return;\n  const hero = document.getElementById('regionDetailHero');\n  const body = document.getElementById('regionDetailBody');\n\n  hero.innerHTML = `\n    <div class=\"region-detail-hero\">\n      <img loading=\"lazy\" src=\"${cfg.image}\" alt=\"${regionName}\">\n      <div class=\"region-detail-over\">\n        <div class=\"region-detail-kicker\">${cfg.status}</div>\n        <div class=\"region-detail-title\">${regionName}</div>\n        <div class=\"region-detail-sub\">${cfg.summary}</div>\n      </div>\n    </div>`;\n\n  const waters = relatedWaterbodies(regionName);\n  const diary = relatedDiary(regionName);\n\n  const watersHtml = waters.length ? waters.map(w=>`\n    <div class=\"region-item\">\n      <div class=\"region-item-title\">${w.name}</div>\n      <div class=\"region-item-sub\">${w.status}</div>\n      <div class=\"region-item-text\">${w.facts.slice(0,2).join(' ')}</div>\n    </div>`).join('') :\n    `<div class=\"region-item\"><div class=\"region-item-title\">Пока нет глубоких карточек</div><div class=\"region-item-text\">Этот регион будет насыщаться через живую разведку и новые выезды.</div></div>`;\n\n  const diaryHtml = diary.length ? diary.map(d=>`\n    <div class=\"region-item\">\n      <div class=\"region-item-title\">${d.place}</div>\n      <div class=\"region-item-sub\">${d.date}</div>\n      <div class=\"region-item-text\"><b>${d.result}</b><br>${d.conclusion}</div>\n    </div>`).join('') :\n    `<div class=\"region-item\"><div class=\"region-item-title\">Личного журнала пока мало</div><div class=\"region-item-text\">Это нормально: регион работает как направление для будущего поиска.</div></div>`;\n\n  body.innerHTML = `\n    <div class=\"card\">\n      <div class=\"region-section-title\"><h3>Статус региона</h3><div class=\"region-mini\">${cfg.status}</div></div>\n      <div class=\"region-summary-grid\">\n        <div class=\"region-metric\"><div class=\"rmk\">Целевые рыбы</div><div class=\"rmv\">${cfg.targets.slice(0,3).join(' / ')}</div></div>\n        <div class=\"region-metric\"><div class=\"rmk\">Записей водоёмов</div><div class=\"rmv\">${waters.length}</div></div>\n        <div class=\"region-metric\"><div class=\"rmk\">Личных записей</div><div class=\"rmv\">${diary.length}</div></div>\n        <div class=\"region-metric\"><div class=\"rmk\">Методы</div><div class=\"rmv\">${cfg.methods.length}</div></div>\n      </div>\n      <button class=\"region-action\" onclick=\"startRegionalResearch('${regionName}')\">ЗАПУСТИТЬ ЖИВУЮ РАЗВЕДКУ ПО РЕГИОНУ</button>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"region-section-title\"><h3>Водоёмы и участки</h3><div class=\"region-mini\">${waters.length}</div></div>\n      ${watersHtml}\n    </div>\n\n    <div class=\"card\">\n      <div class=\"region-section-title\"><h3>Личный опыт</h3><div class=\"region-mini\">${diary.length}</div></div>\n      ${diaryHtml}\n    </div>\n\n    <div class=\"card\">\n      <div class=\"region-section-title\"><h3>Что здесь ловим</h3></div>\n      <div class=\"kchips\">${cfg.targets.map(x=>`<span>${x}</span>`).join('')}</div>\n      <div class=\"klabel\">Основные методы</div>\n      <div class=\"kchips\">${cfg.methods.map(x=>`<span>${x}</span>`).join('')}</div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"region-section-title\"><h3>Что исследовать дальше</h3></div>\n      ${cfg.research.map((x,i)=>`<div class=\"region-item\"><div class=\"region-item-title\">${i+1}. Задача</div><div class=\"region-item-text\">${x}</div></div>`).join('')}\n    </div>`;\n  previousScreen = 'home';\n  go('region', false);\n}\n\nfunction startRegionalResearch(regionName){\n  const cfg = REGION_DETAIL[regionName];\n  go('research');\n  const input = document.getElementById('researchOrigin');\n  if(input) input.value = cfg.origin;\n  const status = document.getElementById('researchStatus');\n  if(status) status.textContent = `Региональная разведка: ${regionName}. В боевой версии здесь будут свежие отчёты, гидрология, правила, доступ и маршрут от точки старта.`;\n}\n\n\nconst CANDIDATE_POINTS = [{\"rank\": 1, \"title\": \"Карьер ГРЭС — ближняя береговая бровка\", \"region\": \"Излучинск / ХМАО — Югра\", \"lat\": 61.00000, \"lon\": 77.00000, \"target\": \"Щука\", \"structure\": \"береговой свал / нижняя кромка\", \"why\": \"Личная серия: 4 щуки примерно 0.7–2.2 кг. Все поклёвки на VIB, рабочая зона около 5–10 м от берега.\", \"confidence\": \"личный сильный сигнал\", \"image\": \"data:image/webp;base64,\", \"evidence\": \"Персональный опыт; точный профиль глубин ещё нужно промерить.\"}, {\"rank\": 2, \"title\": \"Обь — городской берег\", \"region\": \"Нижневартовск / ХМАО — Югра\", \"lat\": 60.950000, \"lon\": 76.600000, \"target\": \"Судак / щука / другой хищник\", \"structure\": \"глубокая речная кромка / течение\", \"why\": \"На поролон с 12 г было два хищных контакта. Участок интересен доступом к глубине и течению, но берег сложный.\", \"confidence\": \"личные контакты\", \"image\": \"data:image/webp;base64,\", \"evidence\": \"Нужна повторная проверка структуры и дальних бровок.\"}, {\"rank\": 3, \"title\": \"Вах / Излучинск — точка 1\", \"region\": \"ХМАО — Югра\", \"lat\": 60.950311, \"lon\": 76.901621, \"target\": \"Хищник\", \"structure\": \"песчаная береговая полка\", \"why\": \"Точка уже проверялась и была пустой. В рейтинге держится как контрольный отрицательный участок: возвращаться только при изменении воды или новой найденной структуре.\", \"confidence\": \"отрицательный личный тест\", \"image\": \"data:image/webp;base64,\", \"evidence\": \"Не рекомендовать автоматически без нового сигнала.\"}, {\"rank\": 4, \"title\": \"Ахтубинск — ракушечник на течении\", \"region\": \"Астраханская область\", \"lat\": 48.26599, \"lon\": 46.145411, \"target\": \"Окунь / жерех\", \"structure\": \"мелководье + течение + ракушечник\", \"why\": \"Эталонный личный паттерн: окунь почти на каждом забросе, жерех дальше; работали небольшие тонущие шумные VIB.\", \"confidence\": \"личный эталон\", \"image\": \"data:image/webp;base64,\", \"evidence\": \"При повторе искать сочетание ракушки, течения, боя и чаек, а не только старую координату.\"}, {\"rank\": 5, \"title\": \"Астрахань — городская береговая точка\", \"region\": \"Астраханская область\", \"lat\": 46.398523, \"lon\": 48.040125, \"target\": \"Щука\", \"structure\": \"береговой линейный участок\", \"why\": \"Поздний август 2021: около 7 небольших щук примерно за 3 часа, все на VIB/раттлины.\", \"confidence\": \"личный успех\", \"image\": \"data:image/webp;base64,\", \"evidence\": \"Точный водоём/рукав ещё нужно закрепить в геобазе.\"}, {\"rank\": 6, \"title\": \"Избербаш — каменисто-песчаная кромка\", \"region\": \"Дагестан / Каспий\", \"lat\": 42.598532, \"lon\": 47.860646, \"target\": \"Кутум / вобла\", \"structure\": \"камни + песок + прибойная зона\", \"why\": \"22–23.08.2020 был очень сильный краткий подход рыбы. Гипотеза связывает его с волной, ветром и концентрацией корма у кромки.\", \"confidence\": \"сильный личный эпизод\", \"image\": \"data:image/webp;base64,\", \"evidence\": \"Для прогноза нужно сопоставление с ветром, волной и температурой воды.\"}];\n\nfunction encodeCoord(lat, lon){\n  return `${Number(lat).toFixed(6)},${Number(lon).toFixed(6)}`;\n}\n\nfunction yandexRouteUrl(lat, lon){\n  const coord = encodeCoord(lat, lon);\n  return `https://yandex.ru/maps/?mode=routes&rtext=~${encodeURIComponent(coord)}&rtt=auto`;\n}\n\nfunction googleRouteUrl(lat, lon){\n  const coord = encodeCoord(lat, lon);\n  return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(coord)}&travelmode=driving&dir_action=navigate`;\n}\n\nfunction twoGisRouteUrl(lat, lon){\n  return `https://2gis.ru/routeSearch/rsType/car/to/${Number(lon).toFixed(6)},${Number(lat).toFixed(6)}/go`;\n}\n\nfunction mapsMePointUrl(lat, lon, name='Рыболовная точка'){\n  return `mapswithme://map?v=1&ll=${Number(lat).toFixed(6)},${Number(lon).toFixed(6)}&n=${encodeURIComponent(name)}&appname=${encodeURIComponent('Рыбалка — консультант')}`;\n}\n\nconst MAP_PROVIDER_KEY='fishing_map_provider_v1';\nconst MAP_PROVIDERS={\n  yandex:{name:'Яндекс Карты',mark:'Я',note:'Маршрут от текущего местоположения'},\n  dgis:{name:'2ГИС',mark:'2',note:'Маршрут и навигация от текущей позиции'},\n  google:{name:'Google Maps',mark:'G',note:'Маршрут с переходом в навигацию'},\n  mapsme:{name:'MAPS.ME',mark:'M',note:'Открыть точку в офлайн-карте; маршрут — внутри MAPS.ME'}\n};\nlet pendingMapTarget=null;\n\nfunction preferredMapProvider(){\n  try{return localStorage.getItem(MAP_PROVIDER_KEY)||'ask'}catch(e){return 'ask'}\n}\nfunction saveMapProvider(key){\n  try{if(key==='ask')localStorage.removeItem(MAP_PROVIDER_KEY);else localStorage.setItem(MAP_PROVIDER_KEY,key)}catch(e){}\n}\nfunction providerRouteUrl(provider,lat,lon,name){\n  if(provider==='yandex') return yandexRouteUrl(lat,lon);\n  if(provider==='dgis') return twoGisRouteUrl(lat,lon);\n  if(provider==='google') return googleRouteUrl(lat,lon);\n  if(provider==='mapsme') return mapsMePointUrl(lat,lon,name);\n  return '';\n}\nfunction launchMapProvider(provider,lat,lon,name='Рыболовная точка'){\n  const url=providerRouteUrl(provider,lat,lon,name);\n  if(!url) return;\n  if(provider==='mapsme'){\n    const started=Date.now();\n    window.location.href=url;\n    setTimeout(()=>{\n      if(!document.hidden && Date.now()-started<2200) window.open('https://maps.me/','_blank','noopener');\n    },1100);\n  }else{\n    window.open(url,'_blank','noopener');\n  }\n}\nfunction ensureMapProviderSheet(){\n  let wrap=document.getElementById('mapProviderBackdrop');\n  if(wrap) return wrap;\n  wrap=document.createElement('div');\n  wrap.id='mapProviderBackdrop'; wrap.className='map-provider-backdrop';\n  wrap.innerHTML=`<div class=\"map-provider-sheet\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"mapProviderTitle\">\n    <div class=\"map-provider-head\"><div><b id=\"mapProviderTitle\">Открыть маршрут</b><span id=\"mapProviderSubtitle\">Выберите картографический сервис</span></div><button class=\"map-provider-close\" type=\"button\" aria-label=\"Закрыть\">×</button></div>\n    <div class=\"map-provider-list\"></div>\n    <label class=\"map-provider-pref\"><input id=\"mapProviderRemember\" type=\"checkbox\"><span>Запомнить мой выбор. Следующий раз кнопка «Маршрут» откроет этот сервис сразу; изменить выбор можно через кнопку ⋯.</span></label>\n    <div class=\"map-provider-hint\">MAPS.ME открывает координату в офлайн-карте. Если приложение не установлено, откроется сайт MAPS.ME.</div>\n  </div>`;\n  document.body.appendChild(wrap);\n  wrap.querySelector('.map-provider-close').onclick=closeMapProviderSheet;\n  wrap.addEventListener('click',e=>{if(e.target===wrap)closeMapProviderSheet()});\n  return wrap;\n}\nfunction closeMapProviderSheet(){\n  document.getElementById('mapProviderBackdrop')?.classList.remove('open');\n}\nfunction renderMapProviderOptions(){\n  const wrap=ensureMapProviderSheet(),list=wrap.querySelector('.map-provider-list');\n  const current=preferredMapProvider(); list.innerHTML='';\n  Object.entries(MAP_PROVIDERS).forEach(([key,p])=>{\n    const b=document.createElement('button'); b.type='button'; b.className='map-provider-option'+(current===key?' active':'');\n    b.innerHTML=`<span class=\"map-provider-logo\">${p.mark}</span><span class=\"map-provider-copy\"><b>${p.name}</b><span>${p.note}</span></span><span class=\"map-provider-check\">${current===key?'✓':'›'}</span>`;\n    b.onclick=()=>{\n      if(!pendingMapTarget)return;\n      if(wrap.querySelector('#mapProviderRemember').checked) saveMapProvider(key);\n      const t=pendingMapTarget; closeMapProviderSheet(); launchMapProvider(key,t.lat,t.lon,t.name);\n    };\n    list.appendChild(b);\n  });\n}\nfunction openMapChooser(lat,lon,name='Рыболовная точка'){\n  pendingMapTarget={lat:Number(lat),lon:Number(lon),name};\n  const wrap=ensureMapProviderSheet();\n  const pref=preferredMapProvider();\n  wrap.querySelector('#mapProviderRemember').checked=pref!=='ask';\n  wrap.querySelector('#mapProviderSubtitle').textContent=`${name} · ${encodeCoord(lat,lon)}`;\n  renderMapProviderOptions(); wrap.classList.add('open');\n}\nfunction openPreferredMap(lat,lon,name='Рыболовная точка'){\n  const pref=preferredMapProvider();\n  if(pref==='ask' || !MAP_PROVIDERS[pref]) openMapChooser(lat,lon,name);\n  else launchMapProvider(pref,lat,lon,name);\n}\n\nfunction renderPrecisionPoints(){\n  const host = document.getElementById('precisionPoints');\n  if(!host) return;\n  host.innerHTML = '';\n\n  CANDIDATE_POINTS.forEach(p=>{\n    const card = el('div','point-card');\n    const coord = encodeCoord(p.lat,p.lon);\n    card.innerHTML = `\n      <div class=\"point-img\">\n        <img loading=\"lazy\" src=\"${p.image}\" alt=\"${p.title}\">\n        <div class=\"point-over\">\n          <div class=\"point-rank\">#${p.rank}</div>\n          <div class=\"point-conf\">${p.confidence}</div>\n        </div>\n      </div>\n      <div class=\"point-body\">\n        <div class=\"point-title\">${p.title}</div>\n        <div class=\"point-sub\">${p.target} · ${p.structure}</div>\n        <div class=\"coordbox\">\n          <div class=\"coordlabel\">ТОЧНЫЕ КООРДИНАТЫ</div>\n          <div class=\"coordvalue\">${coord}</div>\n        </div>\n        <div class=\"point-why\"><b>Почему здесь:</b> ${p.why}</div>\n        ${routeActionsHtml(p.lat,p.lon,p.title)}\n        <div class=\"quality-strip\">\n          <div class=\"quality-cell\"><div class=\"qk\">ДАННЫЕ</div><div class=\"qv\">${p.confidence}</div></div>\n          <div class=\"quality-cell\"><div class=\"qk\">ПРАВИЛА</div><div class=\"qv\">проверить live</div></div>\n          <div class=\"quality-cell\"><div class=\"qk\">КООРДИНАТА</div><div class=\"qv\">подтверждена</div></div>\n        </div>\n        <div class=\"point-foot\">${p.evidence}</div>\n      </div>`;\n    host.appendChild(card);\n  });\n}\n\nfunction routeActionsHtml(lat, lon, name='Рыболовная точка'){\n  if(lat == null || lon == null) return `\n    <div class=\"route-actions\" style=\"grid-template-columns:1fr!important\">\n      <div class=\"route-disabled\">Маршрут недоступен: координаты не подтверждены</div>\n    </div>`;\n  const safeName=encodeURIComponent(String(name||'Рыболовная точка')).replace(/'/g,'%27');\n  return `<div class=\"route-actions\">\n      <button class=\"route-primary-btn\" type=\"button\" onclick=\"event.stopPropagation();openPreferredMap(${Number(lat)},${Number(lon)},decodeURIComponent('${safeName}'))\">Маршрут</button>\n      <button class=\"route-more-btn\" type=\"button\" aria-label=\"Выбрать карту\" title=\"Выбрать карту\" onclick=\"event.stopPropagation();openMapChooser(${Number(lat)},${Number(lon)},decodeURIComponent('${safeName}'))\">⋯</button>\n    </div>`;\n}\n\nconst LIVE_RESEARCH = {\n  candidates:[\n    {\n      title:\"Карьер ГРЭС, Излучинск\",\n      rank:\"1\",\n      confidence:\"средне-высокая\",\n      reason:\"Самый сильный сигнал — твой собственный недавний результат: 4 щуки, все поклёвки на VIB в 5–10 м от берега. Это конкретнее любого общего «прогноза клёва». Свежих независимых публичных отчётов именно по карьеру пока не найдено.\",\n      signals:[\"личный улов\",\"точный участок\",\"рабочая приманка известна\",\"берег доступен\"]\n    },\n    {\n      title:\"Обь, городской берег Нижневартовска\",\n      rank:\"2\",\n      confidence:\"средняя\",\n      reason:\"Есть твои контакты хищника и подтверждённая глубина/течение, но высокий берег осложняет вываживание. По открытым публичным источникам свежие отчёты по Оби есть, однако они недостаточно локализованы, чтобы переносить их прямо на этот участок.\",\n      signals:[\"личные контакты\",\"рельеф интересный\",\"география публичных отчётов слабая\"]\n    },\n    {\n      title:\"Вах / песчаный берег Излучинска\",\n      rank:\"3\",\n      confidence:\"низкая\",\n      reason:\"Последняя личная разведка дала ноль поклёвок на доступной береговой полке. Пока нет достаточного нового сигнала, который оправдывал бы повтор как первый выбор.\",\n      signals:[\"личный отрицательный тест\",\"структура слабее\",\"нужна новая причина ехать\"]\n    }\n  ],\n  sources:[\n    {\n      name:\"Администрация Нижневартовска / рыбоохрана\",\n      meta:\"26.08.2026 · официальный локальный источник · класс A\",\n      note:\"С 1 сентября до распаления льда действует запрет на ловлю на зимовальных ямах; отдельно перечислены запрещённые виды. Это жёсткий фильтр для любых рекомендаций.\"\n    },\n    {\n      name:\"Правила рыболовства Западно-Сибирского бассейна\",\n      meta:\"редакция от 08.06.2026 · нормативный источник · класс A\",\n      note:\"Используется как базовый юридический слой: разрешённые орудия, ограничения, сроки и специальные зоны.\"\n    },\n    {\n      name:\"AllRivers — гидропост Нижневартовск\",\n      meta:\"публичный гидрологический агрегатор · класс B/A по первоисточнику\",\n      note:\"Подтверждает конкретный гидропост на Оби в Нижневартовске. Текущий локальный числовой ряд нужно забирать в backend и хранить со временем измерения.\"\n    },\n    {\n      name:\"Fishermap / публичные отчёты по Оби\",\n      meta:\"агрегатор отчётов · класс C до локализации\",\n      note:\"Сам факт свежих отчётов по Оби недостаточен: без координат/участка такие записи не поднимают рейтинг Нижневартовска автоматически.\"\n    },\n    {\n      name:\"Общие «прогнозы клёва»\",\n      meta:\"класс D/E без прозрачной модели\",\n      note:\"Не используем проценты типа «щука 94%» как доказательство. Они могут быть лишь слабым дополнительным сигналом после гидрологии и реальных отчётов.\"\n    }\n  ]\n};\n\nfunction researchImage(c){\n  const s = c.title.toLowerCase();\n  if(s.includes('грэс') || s.includes('излуч')) return DATA.assets.spotCareer;\n  if(s.includes('обь')) return DATA.assets.spotOb;\n  if(s.includes('вах')) return DATA.assets.spotNorth;\n  return DATA.assets.heroNizh;\n}\n\nfunction renderResearch(){\n  const host = document.getElementById('rankResults');\n  host.innerHTML = '';\n  LIVE_RESEARCH.candidates.forEach(c=>{\n    const x = el('div','story-card');\n    x.innerHTML = `\n      <div class=\"story-img\">\n        <img loading=\"lazy\" src=\"${researchImage(c)}\" alt=\"${c.title}\">\n        <div class=\"story-over\">\n          <div class=\"story-chip\"><span class=\"story-rank\">#${c.rank}</span></div>\n          <div class=\"story-chip blue\">${c.confidence}</div>\n        </div>\n      </div>\n      <div class=\"story-body\">\n        <h4 class=\"story-title\">${c.title}</h4>\n        <div class=\"story-label\">Почему в списке</div>\n        <div class=\"story-line\">${c.reason}</div>\n        <div class=\"story-tags\">${c.signals.map(s=>`<span>${s}</span>`).join('')}</div>\n        <div class=\"story-note\">Это сравнительный рейтинг кандидатов, а не «процент вероятности клёва».</div>\n      </div>`;\n    x.classList.add('interactive-card');\n    x.addEventListener('click', ()=>{\n      const idx = DATA.spots.findIndex(s => c.title.toLowerCase().includes(s.title.split('—')[0].trim().toLowerCase()) || s.title.toLowerCase().includes(c.title.split(',')[0].trim().toLowerCase()));\n      if(idx >= 0) openSpot(idx,'research');\n    });\n    host.appendChild(x);\n  });\n\n  const ledger = document.getElementById('sourceLedger');\n  ledger.innerHTML = '';\n  LIVE_RESEARCH.sources.forEach(s=>{\n    const x = el('div','sourcecard');\n    x.innerHTML = `<div class=\"sname\">${s.name}</div><div class=\"smeta\">${s.meta}</div><div class=\"snote\">${s.note}</div>`;\n    ledger.appendChild(x);\n  });\n  const warn = el('div','warnbox');\n  warn.innerHTML = 'Локальная HTML-версия показывает сохранённый пример. Живой автоматический обход источников подключается через backend.';\n  ledger.appendChild(warn);\n}\ndocument.getElementById('runResearch').addEventListener('click', ()=>{\n  const o = document.getElementById('researchOrigin').value.trim() || 'не задано';\n  document.getElementById('researchStatus').textContent = `Сохранённый пример разведки: ${o}. В боевой версии здесь будет живой запрос к backend: свежие отчёты → гидрология → правила → доступ → личная модель.`;\n  renderResearch();\n  renderPrecisionPoints();\n});\n\nconst PUBLIC_PREVIEW_REPORTS = [{\"place\":\"Излучинск · карьер ГРЭС\",\"date\":\"27.09.2026\",\"time\":\"13:00–17:00\",\"result\":\"4 щуки: 0,7; 1,5; 1,7; 2,2 кг\",\"method\":\"VIB/раттлины 55–65 мм; проводка у дна или чуть выше, равномерная с рывками.\",\"conclusion\":\"Поклёвки происходили в 5–10 м от берега. Сработали серебристая приманка и тонкий белый VIB с красной головой.\"},{\"place\":\"Ерик Казачий\",\"date\":\"06.08.2022\",\"time\":\"примерно 07:00–10:00\",\"result\":\"Судак и результативная ловля мирной рыбы на прикормленной точке\",\"method\":\"Судак: заброс по течению с лодки; чебурашка, отводной поводок, офсет 4/0, живой малёк.\",\"conclusion\":\"Результат по мирной рыбе относится к заранее прикормленной кем-то точке и не является нормой клёва для всего ерика.\"},{\"place\":\"Ахтубинск\",\"date\":\"07.2021\",\"time\":\"\",\"result\":\"Окунь и жерех\",\"method\":\"Ловля с лодки на мелководной струе с ракушечником; небольшие тонущие шумные VIB/раттлины.\",\"conclusion\":\"Окунь попадался почти на каждом забросе, жерех держался дальше и требовал дальнего заброса.\"},{\"place\":\"Заволжское\",\"date\":\"27.09.2023 — 01.10.2023\",\"time\":\"\",\"result\":\"Улов не зафиксирован\",\"method\":\"Детали приманок и конкретных точек не сохранены.\",\"conclusion\":\"Запись неполная; использовать как подтверждение условий или эффективности метода нельзя.\"},{\"place\":\"Красный Яр\",\"date\":\"08.2024\",\"time\":\"\",\"result\":\"Детали улова сохранены частично\",\"method\":\"Для жереха зафиксирован отдельный донный сценарий на живого малька на глубине более 10 м.\",\"conclusion\":\"Запись требует восстановления деталей перед использованием в статистике.\"}];\n// Restore lists from data already present in the public preview.\nDATA.diary = PUBLIC_PREVIEW_REPORTS;\nDATA.spots = CANDIDATE_POINTS.map(p => ({title:p.title,img:p.image,fish:p.target,meta:p.why,distance:p.region,badge:p.confidence}));\nDATA.regions = Object.entries(REGION_DETAIL).map(([name,r]) => ({name,img:r.image,summary:r.summary}));\ntry{ renderFish25Home(); }catch(err){ console.error('Initial fish render failed:',err); }\n\nconst SAFE_INIT = (name,fn)=>{ try{ fn(); }catch(err){ console.error('Init '+name+' failed:',err); } };\nSAFE_INIT('waters',renderWaters);\nSAFE_INIT('methods',renderMethods);\nSAFE_INIT('gear',renderGear);\nSAFE_INIT('lures',renderLures);\nSAFE_INIT('knowledge',renderKnowledge);\nSAFE_INIT('researchBase',renderResearchBase);\nSAFE_INIT('precisionPoints',renderPrecisionPoints);\nSAFE_INIT('activity',renderActivity);\ncheckBackend();\nSAFE_INIT('spotsBlock',()=>renderSpots('spotsBlock'));\nSAFE_INIT('mapSpotsBlock',()=>renderSpots('mapSpotsBlock'));\nSAFE_INIT('regions',renderRegions);\nSAFE_INIT('diary',renderDiary);\nSAFE_INIT('homeDiaryPreview',renderHomeDiaryPreview);\n\ndocument.getElementById('fishHomeSearch')?.addEventListener('input',fish25HomeSearch);\ndocument.getElementById('fishHomeClear')?.addEventListener('click',()=>{const i=document.getElementById('fishHomeSearch');i.value='';fish25HomeSearch();i.focus();});\ndocument.getElementById('fishGroupSearch')?.addEventListener('input',renderFish25Group);\ndocument.getElementById('fishGroupClear')?.addEventListener('click',()=>{const i=document.getElementById('fishGroupSearch');i.value='';renderFish25Group();i.focus();});\n\nrenderTrips();\nrenderResearch();\n\nasync function checkBackend(){\n  const text = document.getElementById('backendStatusText');\n  const badge = document.getElementById('backendStatusBadge');\n  if(!text || !badge) return;\n  try{\n    const r = await fetch('/api/health', {cache:'no-store'});\n    if(!r.ok) throw new Error('http');\n    const j = await r.json();\n    text.textContent = `Подключён API ${j.version}. Live-запросы можно выполнять через серверный pipeline.`;\n    badge.textContent = 'LIVE';\n    badge.style.color = '#57ea91';\n  }catch(e){\n    text.textContent = 'Backend не подключён. Показаны только сохранённые примеры и личные подтверждённые точки.';\n    badge.textContent = 'OFFLINE';\n    badge.style.color = '#ffd45f';\n  }\n}\n\n\nlet fishingMap = null;\nfunction initRealMap(){\n  const host = document.getElementById('realFishingMap');\n  const fallback = document.getElementById('mapFallback');\n  if(!host) return;\n  if(typeof L === 'undefined'){\n    if(fallback) fallback.style.display='block';\n    return;\n  }\n  if(fishingMap){\n    setTimeout(()=>fishingMap.invalidateSize(), 50);\n    return;\n  }\n  fishingMap = L.map(host, {zoomControl:true});\n  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{\n    maxZoom:19,\n    attribution:'© OpenStreetMap contributors'\n  }).addTo(fishingMap);\n\n  const bounds = [];\n  CANDIDATE_POINTS.forEach((p, idx)=>{\n    if(typeof p.lat!=='number' || typeof p.lon!=='number') return;\n    const marker = L.marker([p.lat,p.lon]).addTo(fishingMap);\n    const popupName=encodeURIComponent(String(p.title||'Рыболовная точка')).replace(/'/g,'%27');\n    marker.bindPopup(`<div class=\"map-popup-title\">${p.title}</div><div class=\"map-popup-sub\">${p.target} · ${p.structure}<br>${encodeCoord(p.lat,p.lon)}</div><button class=\"map-popup-route\" type=\"button\" onclick=\"openPreferredMap(${p.lat},${p.lon},decodeURIComponent('${popupName}'))\">Маршрут</button>`);\n    marker.on('click', ()=>{fishingMap.setView(marker.getLatLng(), Math.max(fishingMap.getZoom(),13));});\n    bounds.push([p.lat,p.lon]);\n  });\n  if(bounds.length) fishingMap.fitBounds(bounds, {padding:[24,24], maxZoom:11});\n  else fishingMap.setView([55.75,37.62], 5);\n}\n\n\n\n\n\ndocument.addEventListener('click', (e)=>{\n  const item = e.target.closest('[data-goto]');\n  if(!item) return;\n  const route = item.dataset.goto;\n  if(route){\n    e.preventDefault();\n    go(route);\n  }\n});\n\n</script>\n<script src=\"personal-diary-ui.js?v=20260930-gear1\"></script>\n</body>\n</html>\n";